+/// A plain round bar of radius 3 from station `x0` to `x1`, laid along x.
+fn laid_stock(x0: f64, x1: f64) -> Vec<Triangle> {
+    revolve(16, &[(0.0, x0), (3.0, x0), (3.0, x1), (0.0, x1)])
+        .into_iter()
+        .map(|f| Triangle::new(laid(f.a), laid(f.b), laid(f.c)))
+        .collect()
